  const sMin = rMin - sPad
  const sMax = rMax + sPad
  // Seeded (not Math.random()) so the jitter doesn't reshuffle every time
  // spreadStage changes and this cell re-runs — same student, same dots.
  const seededRandom = (seed) =&gt; { const x = Math.sin(seed * 12.9898) * 43758.5453; return x - Math.floor(x) }
  const jittered = vals.map((v, i) =&gt; ({ v, y: (seededRandom(i) - 0.5) * 1.0 }))

  const showSD  = spreadStage === 'sd' || spreadStage === 'iqr'
  const showIQR = spreadStage === 'iqr'

  const stageDescription = {
    none:   "no measure of spread is highlighted yet",
    range:  `the full range is shaded, from the minimum ${rMin.toFixed(0)} ms to the maximum ${rMax.toFixed(0)} ms`,
    sd:     `one standard deviation either side of the mean is shaded, from ${(mu-sig).toFixed(0)} to ${(mu+sig).toFixed(0)} ms`,
    iqr:    `the interquartile range is shaded, from the 25th percentile ${q1.toFixed(0)} ms to the 75th percentile ${q3.toFixed(0)} ms`,
    '90-10': `the middle 80% is shaded, from the 10th percentile ${p10.toFixed(0)} ms to the 90th percentile ${p90.toFixed(0)} ms`,
  }[spreadStage]

  return accessibleChart(Plot.plot({
    height: 220,
    marginLeft: 55,
    x: { label: "Reaction time (ms)", domain: [sMin, sMax] },
    // Fixed, explicit domain — without it, Plot auto-computes the y-domain
    // from whichever marks are present, and the highlight rects (y1/y2 =
    // -0.6/0.6) are wider than the dots alone (-0.5/0.5). That meant the
    // very first transition (no highlight -&gt; a highlight appearing) widened
    // the auto-domain and visibly shifted the dots; every later transition
    // was stable since a rect was already present. Matching the rects'
    // extent with a little padding keeps every stage on the same domain.
    y: { axis: null, domain: [-0.7, 0.7] },
    marks: [
      spreadStage === 'range' ? Plot.rectX([{ x1: rMin, x2: rMax }],
        { x1: "x1", x2: "x2", y1: -0.6, y2: 0.6, fill: "#2d6a4f", fillOpacity: 0.15 }) : null,
