      Plot.dot(jittered, { x: "v", y: "y", fill: "#457b9d", r: 5, fillOpacity: 0.7 }),
      showSD ? Plot.ruleX([mu], { stroke: "#e63946", strokeWidth: 2.5 }) : null,
      spreadStage === 'range' ? Plot.text([
