      showSD ? Plot.text([
        { x: mu,        label: `Mean: ${mu.toFixed(1)}`          },
        { x: mu - sig,  label: `−1 SD (${(mu-sig).toFixed(0)})` },
        { x: mu + sig,  label: `+1 SD (${(mu+sig).toFixed(0)})` },
      ], { x: "x", text: "label", dy: -32, fill: "#e63946", fontSize: 11 }) : null,
      showIQR ? Plot.text([
        { x: (q1+q3)/2, label: `IQR: ${q1.toFixed(0)}–${q3.toFixed(0)} ms` }
      ], { x: "x", text: "label", dy: 38, fill: "#f4a261", fontSize: 12 }) : null,
      spreadStage === '90-10' ? Plot.text([
        { x: p10, label: `P10 (${p10.toFixed(0)})` },
        { x: p90, label: `P90 (${p90.toFixed(0)})` },
      ], { x: "x", text: "label", dy: -32, fill: "#1d3557", fontSize: 11 }) : null,
    ]
  }), `This chart builds up different measures of spread — range, standard deviation, interquartile range, or the 90-10 range — by highlighting each on the same data as it's introduced. Here, on ${spread_student}'s ten reaction times: ${stageDescription}.`)
}







Range = max − min. Simple but dominated by extremes.


SD = √variance. Same units as the data. Sensitive to outliers.


IQR = Q3 − Q1. Spread of the middle 50%. Robust to outliers.


90–10 range = 90th percentile − 10th percentile. A middle ground — trims the most extreme 20% without being as narrow as the IQR.

