      Plot.ruleX([0]),
    ]
  }), "This chart shows the characteristic bell shape of a normal distribution, so it can be recognised later in real data. 4,000 simulated draws, symmetric and peaking at zero.")
}

The log-normal distribution



Normal arises from summing many small, independent effects. Log-normal arises from multiplying them — and since \(\log(a \times b) = \log a + \log b\), the log of such a variable is itself a sum, so it’s approximately normal
Transform a normal \(x\) with \(e^x\) and you get exactly this: always non-negative, long right tail
Examples: income, firm size, our reaction-time data — each the result of many small multiplicative factors (attention, motor noise, distraction, …)




{
  const rng = d3.randomLogNormal(0, 0.5)
  const sample = Array.from({ length: 4000 }, rng)
  const cutoff = d3.quantile(sample.slice().sort(d3.ascending), 0.99)
  return accessibleChart(Plot.plot({
    height: 420,
    x: { label: "x", domain: [0, cutoff] },
    y: { label: "% of draws", percent: true },
    marks: [
      Plot.rectY(sample.filter(d =&gt; d &lt;= cutoff), Plot.binX({ y: "proportion" },
        { x: d =&gt; d, thresholds: 30, fill: "#2d6a4f", fillOpacity: 0.8 })),
      Plot.ruleX([0]),
    ]
  }), "This chart shows the characteristic right-skewed shape of a log-normal distribution, for comparison with the normal distribution shown earlier. 4,000 simulated draws, most values near zero with a long tail of larger ones.")
}

The power-law distribution



Also called the Pareto distribution — large extreme values are common at any scale
Examples: city population, word frequency, wealth




{
  const alpha = 2.5, xmin = 1
  const sample = Array.from({ length: 4000 }, () =&gt; xmin * Math.pow(1 - Math.random(), -1 / alpha))
  const cutoff = d3.quantile(sample.slice().sort(d3.ascending), 0.97)
  return accessibleChart(Plot.plot({
    height: 420,
    x: { label: "x", domain: [0, cutoff] },
    y: { label: "% of draws", percent: true },
    marks: [
      Plot.rectY(sample.filter(d =&gt; d &lt;= cutoff), Plot.binX({ y: "proportion" },
        { x: d =&gt; d, thresholds: 30, fill: "#e63946", fillOpacity: 0.8 })),
      Plot.ruleX([0]),
    ]
  }), "This chart shows the characteristic shape of a power-law distribution, where extreme values are far more common than in a normal or log-normal distribution. 4,000 simulated draws, almost all small with a very long thin tail of much larger values.")
}









