}







{
  const mu0 = 0, mu1 = effect_size, sigma = 1, crit = 2
  const xs = d3.range(-5, 7.51, 0.05)
  const pdf = (x, mu) =&gt; (1 / (sigma * Math.sqrt(2 * Math.PI))) * Math.exp(-0.5 * ((x - mu) / sigma) ** 2)
  const nullCurve = xs.map(x =&gt; ({ x, y: pdf(x, mu0) }))
  const altCurve  = xs.map(x =&gt; ({ x, y: pdf(x, mu1) }))
  const nullReject = xs.filter(x =&gt; x &gt; crit).map(x =&gt; ({ x, y: pdf(x, mu0) }))
  const altMiss     = xs.filter(x =&gt; x &lt; crit).map(x =&gt; ({ x, y: pdf(x, mu1) }))
  const altHit       = xs.filter(x =&gt; x &gt; crit).map(x =&gt; ({ x, y: pdf(x, mu1) }))

  const power = 1 - jStat_norm_cdf(crit - mu1)
  function jStat_norm_cdf(z) {
    return 0.5 * (1 + erf(z / Math.SQRT2))
  }
  function erf(x) {
    const sign = x &lt; 0 ? -1 : 1
    x = Math.abs(x)
    const a1=0.254829592, a2=-0.284496736, a3=1.421413741, a4=-1.453152027, a5=1.061405429, p=0.3275911
    const t = 1/(1+p*x)
    const y = 1 - (((((a5*t+a4)*t)+a3)*t+a2)*t+a1)*t*Math.exp(-x*x)
    return sign*y
  }

  return Plot.plot({
    height: 320,
    marginLeft: 50,
    marginBottom: 34,
    x: { label: "t-statistic", domain: [-5, 7.5] },
    y: { label: "density" },
    marks: [
      Plot.areaY(nullReject, { x: "x", y: "y", fill: "#e63946", fillOpacity: 0.55 }),
      Plot.areaY(altMiss,    { x: "x", y: "y", fill: "#f4a261", fillOpacity: 0.45 }),
      Plot.areaY(altHit,     { x: "x", y: "y", fill: "#2d6a4f", fillOpacity: 0.35 }),
      Plot.line(nullCurve, { x: "x", y: "y", stroke: "#1a1a2e", strokeWidth: 2 }),
      Plot.line(altCurve,  { x: "x", y: "y", stroke: "#457b9d", strokeWidth: 2 }),
      Plot.ruleX([crit, -crit], { stroke: "#666", strokeWidth: 1, strokeDasharray: "4,3" }),
      Plot.ruleY([0]),
      Plot.text([{ x: -5, y: pdf(0,0)*1.05, label: `Power ≈ ${(power*100).toFixed(0)}%` }],
                { x: "x", y: "y", text: "label", textAnchor: "start", fill: "#2d6a4f", fontSize: 13, fontWeight: 700 }),
    ]
  })
}







Black = null distribution. Blue = alternative (true effect). Red = Type I error (false positive) region. Orange = Type II error (false negative, missed). Green = power. Drag the slider to 0 and watch the curves merge — no true effect means no power, only the 5% false-positive rate remains.


Pattern after Békés & Kézdi (2021), Ch. 6

