{
  const n = 200
  const seed = i =&gt; { const s = Math.sin(i * 12.9898) * 43758.5453; return (s - Math.floor(s)) * 2 - 1 }
  const seed2 = i =&gt; { const s = Math.sin(i * 78.233) * 12345.6789; return (s - Math.floor(s)) * 2 - 1 }
  const x1 = d3.range(n).map(i =&gt; seed(i))
  const x2 = d3.range(n).map(i =&gt; corrSlider * x1[i] + Math.sqrt(1 - corrSlider ** 2) * seed2(i))
  const y = d3.range(n).map(i =&gt; 2 * x1[i] + 1.5 * x2[i] + seed2(i * 3.1))
  const fitFor = c =&gt; {
    const x2c = d3.range(n).map(i =&gt; c * x1[i] + Math.sqrt(1 - c ** 2) * seed2(i))
    const model = olsFit(x1.map((v, i) =&gt; [v, x2c[i]]), y)
    const sdE = Math.sqrt(d3.sum(model.resid.map(e =&gt; e ** 2)) / (n - model.k))
    const sdX1 = Math.sqrt(d3.mean(x1.map(v =&gt; (v - d3.mean(x1)) ** 2)))
    const auxR2 = (() =&gt; {
      const aux = olsFit(x2c.map(v =&gt; [v]), x1)
      const ybar = d3.mean(x1)
      const varY = d3.mean(x1.map(v =&gt; (v - ybar) ** 2))
      const varYhat = d3.mean(aux.fitted.map(f =&gt; (f - ybar) ** 2))
      return varYhat / varY
    })()
    return sdE / (Math.sqrt(n) * sdX1 * Math.sqrt(1 - auxR2))
  }
  const curve = d3.range(0, 0.99, 0.02).map(c =&gt; ({ c, se: fitFor(c) }))
  const currentSE = fitFor(corrSlider)
  const chart = Plot.plot({
    height: 320, marginLeft: 60,
    x: { label: "correlation between x₁ and x₂" }, y: { label: "SE(β̂₁)" },
    marks: [
      Plot.line(curve, { x: "c", y: "se", stroke: "#457b9d", strokeWidth: 2 }),
      Plot.dot([{ c: corrSlider, se: currentSE }], { x: "c", y: "se", fill: "#e63946", r: 6 }),
    ]
  })
  return html`&lt;div&gt;${chart}&lt;p style="font-family:sans-serif;font-size:1em;text-align:center;"&gt;SE(β̂₁) at this correlation: &lt;strong&gt;${currentSE.toFixed(3)}&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;`
}







Simulated data, true coefficients fixed throughout. Drag the correlation up. The point estimate barely changes — but watch the SE climb, slowly at first, then sharply as correlation approaches 1.

